var i=`0632-hawawshi`;var t=`world-0632`;var a=`EG`;var o=`northern-africa`;var s=4;var r=109;var g={en:`Hawawshi`,ua:`Хававші`};var l={en:`Hawawshi is a Egypt classic prepared with all-purpose flour, instant yeast, ground beef, yellow onion. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Хававші, страва кухні країни Єгипет зі складниками: пшеничне борошно універсальне, інстантні дріжджі, яловичий фарш, жовта цибуля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 60 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 60 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:60,i:[[`all-purpose-flour`,480,`g`],[`water`,300,`ml`],[`instant-yeast`,6,`g`],[`table-salt`,6,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-beef`,520,`g`],[`yellow-onion`,180,`g`],[`tomato`,190,`g`],[`parsley`,20,`g`],[`ground-cumin`,5,`g`]]},{en:`Divide the dough, spread minced beef thinly between two layers or inside each flattened bread, and seal the edges.`,ua:`Розділіть тісто, розподіліть тонкий шар яловичого фаршу між двома шарами або всередині кожного коржа й защипніть краї.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Roast in a preheated 190°C oven for about 24 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 24 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:24,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon`,1,`pcs`]]}];var u={slug:i,id:t,country:`EG`,region:o,servings:4,minutes:109,title:g,text:l,steps:d};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,i as slug,d as steps,l as text,g as title};